//! 📦️ Original payload storage initializes and fills in place before a semantic borrow is sealed.
use super::*;
use std::mem::size_of;
use semio_framework_value::RetirementDemand;

/// 🎟️ Owns one paid original operation ledger; genuine caller turns borrow it until separate closure.
pub struct JobPayloadAuthority{original:ManuallyDrop<Option<Arc<JobPayloadOperationLedger>>>}
impl JobPayloadAuthority{
 pub fn admission_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<JobPayloadOperationLedger>()+2*size_of::<usize>()+size_of::<Option<Arc<JobPayloadOperationLedger>>>(),capacity_bytes:semio_framework_value::shared_retirement_allocation_bytes::<JobPayloadOperationLedger>(),depth:1,..Default::default()}}
 fn permits(grant:RetainedCloneGrant,demand:RetirementDemand)->bool{grant.maximum_items>0&&grant.maximum_copy_bytes>=demand.copy_bytes&&grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes&&grant.maximum_depth>=demand.depth}
 pub fn admit(operation:OperationId,generation:Generation,grant:RetainedCloneGrant)->Result<Option<(Self,RetainedCloneProgress)>,ValueError>{let demand=Self::admission_demand();if !Self::permits(grant,demand){return Ok(None)}let original=Some(Arc::new(JobPayloadOperationLedger::new(operation,generation)));Ok(Some((Self{original:ManuallyDrop::new(original)},RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,retained_capacity_bytes:demand.capacity_bytes,released_bytes:0})))}
 pub(super) fn original(&self)->Option<&Arc<JobPayloadOperationLedger>>{self.original.as_ref()}
 pub fn terminal_is_empty(&self)->bool{self.original.is_none()}
 pub fn retirement_demands(&self)->RetirementDemand{if self.terminal_is_empty(){return Default::default()}RetirementDemand{copy_bytes:Self::admission_demand().copy_bytes,release_bytes:semio_framework_value::shared_retirement_allocation_bytes::<JobPayloadOperationLedger>(),depth:1,..Default::default()}}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let demand=self.retirement_demands();if !Self::permits(grant,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}let original=self.original.take().unwrap();let (copied_bytes,released_bytes)=if let Some(original)=Arc::into_inner(original){drop(original);(demand.copy_bytes,demand.release_bytes)}else{(size_of::<Option<Arc<JobPayloadOperationLedger>>>()+size_of::<usize>(),0)};Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes,retained_capacity_bytes:0,released_bytes}))}
}
impl Drop for JobPayloadAuthority{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original payload authority reached Drop before separate paid ledger closure");}}

/// 🧱️ Enclosing job admission owns this storage; bounded turns initialize its original fields.
pub struct RetainedPayloadBuilder{original:MaybeUninit<RetainedJobPayload>,stream:JobPayloadStream,initialized:usize,ready:bool,sealed:bool}
impl RetainedPayloadBuilder{
 pub fn new(stream:JobPayloadStream)->Self{Self{original:MaybeUninit::uninit(),stream,initialized:0,ready:false,sealed:false}}
 pub fn original(&self)->Option<&RetainedJobPayload>{self.ready.then(||unsafe{self.original.assume_init_ref()})}
 pub fn published(&self)->Option<&RetainedJobPayload>{if self.sealed{self.original()}else{None}}
 pub fn is_initialized(&self)->bool{self.ready}
 pub fn terminal_is_empty(&self)->bool{!self.ready&&self.initialized==0}
 fn permits(cx:&StepContext<'_>,demand:RetirementDemand)->bool{let grant=cx.retained_grant();grant.maximum_items>0&&grant.maximum_copy_bytes>=demand.copy_bytes&&grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes&&grant.maximum_depth>=demand.depth}
 pub fn initialization_demand(&self)->RetirementDemand{if self.ready{return Default::default()}let copy_bytes=if self.initialized<JOB_PAYLOAD_OPERATION_PAGES{size_of::<Option<JobPayloadPage>>()+size_of::<usize>()}else{size_of::<JobPayloadStream>()+2*size_of::<usize>()+size_of::<Option<Arc<JobPayloadOperationLedger>>>()+2*size_of::<bool>()};RetirementDemand{copy_bytes,depth:1,..Default::default()}}
 /// 🎛️ Initializes only admitted original bindings or the separately paid scalar header.
 pub fn advance_initialization(&mut self,cx:&mut StepContext<'_>)->Result<bool,ValueError>{if self.ready{return Ok(true)}let demand=self.initialization_demand();if !Self::permits(cx,demand){return Ok(false)}let copy_bytes;if self.initialized<JOB_PAYLOAD_OPERATION_PAGES{let count=((cx.retained_grant().maximum_copy_bytes-size_of::<usize>())/size_of::<Option<JobPayloadPage>>()).min(JOB_PAYLOAD_OPERATION_PAGES-self.initialized);let target=self.original.as_mut_ptr();for index in self.initialized..self.initialized+count{unsafe{std::ptr::addr_of_mut!((*target).pages).cast::<Option<JobPayloadPage>>().add(index).write(None);}}self.initialized+=count;copy_bytes=count*size_of::<Option<JobPayloadPage>>()+size_of::<usize>();}else{let target=self.original.as_mut_ptr();unsafe{std::ptr::addr_of_mut!((*target).stream).write(self.stream);std::ptr::addr_of_mut!((*target).page_count).write(0);std::ptr::addr_of_mut!((*target).length).write(0);std::ptr::addr_of_mut!((*target).ledger).write(ManuallyDrop::new(None));}self.ready=true;self.sealed=false;copy_bytes=demand.copy_bytes;}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copy_bytes,..Default::default()})?;Ok(self.ready)}
 fn append_metadata(&self)->Result<(bool,usize),ValueError>{let Some(payload)=self.original()else{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original payload bindings are not initialized"))};if self.sealed{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original published payload cannot append"))}let new=payload.page_count==0||payload.pages[payload.page_count-1].as_ref().is_some_and(|page|page.length==JOB_PAYLOAD_PAGE_BYTES);let metadata=if new{5*size_of::<usize>()+size_of::<Option<JobPayloadPage>>()+3*size_of::<usize>()+usize::from(payload.ledger.is_none())*2*size_of::<Option<Arc<JobPayloadOperationLedger>>>()}else{2*size_of::<usize>()};Ok((new,metadata+size_of::<usize>()+size_of::<bool>()))}
 pub fn append_demand(&self)->Result<RetirementDemand,ValueError>{let(new,metadata)=self.append_metadata()?;Ok(RetirementDemand{copy_bytes:metadata+1,capacity_bytes:if new{JOB_PAYLOAD_PAGE_BYTES}else{0},depth:1,..Default::default()})}
 /// ✍️ Copies one admitted original slice directly into its retained native page and records every effect.
 pub fn append_original(&mut self,cx:&mut StepContext<'_>,source:&[u8],cursor:&mut usize)->Result<bool,ValueError>{if *cursor>source.len(){return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original payload source cursor exceeds its borrowed extent"))}if *cursor==source.len(){return Ok(true)}let demand=self.append_demand()?;if !Self::permits(cx,demand)||cx.payload_page_granted{return Ok(false)}let(new,metadata)=self.append_metadata()?;let grant=cx.retained_grant();let payload=unsafe{self.original.assume_init_mut()};if payload.ledger.as_ref().is_some_and(|ledger|!Arc::ptr_eq(ledger,&cx.payload_ledger)){return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original payload append requires its same operation ledger"))}if new&&payload.page_count>=JOB_PAYLOAD_OPERATION_PAGES{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original payload has no remaining admitted page binding"))}let remaining=if new{JOB_PAYLOAD_PAGE_BYTES}else{JOB_PAYLOAD_PAGE_BYTES-payload.pages[payload.page_count-1].as_ref().unwrap().length};let count=(grant.maximum_copy_bytes-metadata).min(remaining).min(source.len()-*cursor);if new{match cx.payload_ledger.reserve_original(payload.stream){Ok(_)=>{},Err((fault,copy_bytes))=>{let progress=RetainedCloneProgress{copied_items:usize::from(copy_bytes>0),copied_bytes:copy_bytes,..Default::default()};cx.consume_retained(progress)?;return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,match fault{JobPayloadAdmissionFault::OperationItems=>"original operation page count refused",JobPayloadAdmissionFault::OperationBytes=>"original operation page extent refused",JobPayloadAdmissionFault::StreamItems=>"original stream page count refused",JobPayloadAdmissionFault::StreamBytes=>"original stream page extent refused",_=>"original process page extent refused"}).with_retained_progress(progress))}}let page=JobPayloadPage{source:JobPayloadPageSource::new(),length:0};payload.pages[payload.page_count]=Some(page);payload.page_count+=1;if payload.ledger.is_none(){*payload.ledger=Some(Arc::clone(&cx.payload_ledger));}}let page=payload.pages[payload.page_count-1].as_mut().unwrap();unsafe{std::ptr::copy_nonoverlapping(source.as_ptr().add(*cursor),page.source.storage.as_mut_ptr().cast::<u8>().add(page.length),count);}page.length+=count;payload.length+=count;*cursor+=count;cx.payload_page_granted=true;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:count+metadata,retained_capacity_bytes:if new{JOB_PAYLOAD_PAGE_BYTES}else{0},released_bytes:0})?;Ok(*cursor==source.len())}
 /// 🔏️ Seals this same original header for borrowed semantic consumption without a finish transfer.
 pub fn seal(&mut self,cx:&mut StepContext<'_>)->Result<bool,ValueError>{if !self.ready{return Ok(false)}if self.sealed{return Ok(true)}let demand=RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()};if !Self::permits(cx,demand){return Ok(false)}self.sealed=true;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})?;Ok(true)}
 pub fn retirement_demands(&self)->Result<RetirementDemand,ValueError>{if let Some(payload)=self.original(){if !payload.terminal_is_empty(){let mut demand=payload.retirement_demands()?;demand.depth=demand.depth.checked_add(1).ok_or_else(||ValueError::literal(ValueRefusalKind::DepthLimit,"original payload builder depth overflow"))?;return Ok(demand)}}Ok(RetirementDemand{copy_bytes:if self.terminal_is_empty(){0}else{size_of::<usize>()+size_of::<bool>()},depth:usize::from(!self.terminal_is_empty()),..Default::default()})}
 /// ♻️ Original pages and ledger close before a separate in-place metadata removal turn.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,ValueError>{if self.terminal_is_empty(){return Ok(true)}let demand=self.retirement_demands()?;if !Self::permits(cx,demand){return Ok(false)}if self.original().is_some_and(|payload|!payload.terminal_is_empty()){let grant=RetainedCloneGrant{maximum_depth:cx.retained_grant().maximum_depth-1,..cx.retained_grant()};match unsafe{self.original.assume_init_mut()}.close_step(grant){Ok(step)=>cx.consume_retained(step.progress())?,Err(error)=>{cx.consume_retained(error.retained_progress())?;return Err(error)}}return Ok(false)}if self.ready{unsafe{self.original.assume_init_drop();}}self.ready=false;self.initialized=0;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})?;Ok(true)}
}
impl Drop for RetainedPayloadBuilder{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original payload builder reached Drop before physical closure and in-place metadata removal");}}
